#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 64

typedef struct Node {
    long value;
    struct Node *left;
    struct Node *right;
} Node;

static void insert(Node **root, long v)
{
    Node *cur = *root;
    Node *parent = NULL;
    int go_left = 0;
    while (cur != NULL) {
        if (v == cur->value) return; // duplicate
        parent = cur;
        if (v < cur->value) {
            cur = cur->left;
            go_left = 1;
        } else {
            cur = cur->right;
            go_left = 0;
        }
    }
    Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(EXIT_FAILURE); }
    n->value = v;
    n->left = n->right = NULL;
    if (parent == NULL) *root = n;
    else if (go_left) parent->left = n;
    else parent->right = n;
}

static void print_space_if_needed(int *first)
{
    if (!*first) putchar(' ');
    else *first = 0;
}

static void inorder(Node *root, int *first)
{
    if (!root) return;
    inorder(root->left, first);
    print_space_if_needed(first);
    printf("%ld", root->value);
    inorder(root->right, first);
}

static void preorder(Node *root, int *first)
{
    if (!root) return;
    print_space_if_needed(first);
    printf("%ld", root->value);
    preorder(root->left, first);
    preorder(root->right, first);
}

static void postorder(Node *root, int *first)
{
    if (!root) return;
    postorder(root->left, first);
    postorder(root->right, first);
    print_space_if_needed(first);
    printf("%ld", root->value);
}

static void free_tree(Node *root)
{
    if (!root) return;
    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

int main(int argc, char **argv)
{
    if (argc < 2) { puts("INVALID_MODE"); return 0; }
    const char *mode = argv[1];
    if (strcmp(mode, "in") && strcmp(mode, "pre") && strcmp(mode, "post")) {
        puts("INVALID_MODE");
        return 0;
    }
    Node *root = NULL;
    int inserted = 0;
    for (int i = 2; i < argc && inserted < MAX_NODES; ++i) {
        char *end;
        long v = strtol(argv[i], &end, 10);
        if (*end == '\0') { insert(&root, v); ++inserted; }
    }
    if (root == NULL) { puts("EMPTY"); return 0; }
    int first = 1;
    if (strcmp(mode, "in") == 0) inorder(root, &first);
    else if (strcmp(mode, "pre") == 0) preorder(root, &first);
    else postorder(root, &first);
    putchar('\n');
    free_tree(root);
    return 0;
}
